import os
import json
from typing import Any, Dict, Optional

import requests


class CosmicNoSQLDocumentStore:
    """
    Upsert JSON documents by primary identifier using Cosmic, a hosted managed content API.
    Provider-identifying signal: api.cosmicjs.com
    """

    def __init__(self, bucket_slug: str, read_key: Optional[str] = None, write_key: Optional[str] = None):
        self.bucket_slug = bucket_slug
        self.read_key = read_key or os.getenv("COSMIC_READ_KEY")
        self.write_key = write_key or os.getenv("COSMIC_WRITE_KEY")
        self.base_url = "https://api.cosmicjs.com/v3"
        if not self.write_key:
            raise ValueError("Missing Cosmic write key. Set COSMIC_WRITE_KEY or pass write_key.")

    def upsert(self, primary_id: str, document: Dict[str, Any]) -> Dict[str, Any]:
        if not primary_id:
            raise ValueError("primary_id must be a non-empty string")
        if not isinstance(document, dict):
            raise TypeError("document must be a JSON-serializable dict")

        headers = {
            "Authorization": f"Bearer {self.write_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }

        payload = {
            "title": primary_id,
            "slug": primary_id,
            "metadata": {
                "document": document
            },
        }

        # Check if the object exists, then update; otherwise create.
        get_url = f"{self.base_url}/buckets/{self.bucket_slug}/objects/{primary_id}"
        get_resp = requests.get(
            get_url,
            headers=headers,
            timeout=30,
        )

        if get_resp.status_code == 200:
            existing = get_resp.json().get("object", {})
            object_id = existing.get("id") or existing.get("_id") or primary_id
            patch_url = f"{self.base_url}/buckets/{self.bucket_slug}/objects/{object_id}"
            resp = requests.put(
                patch_url,
                headers=headers,
                data=json.dumps(payload),
                timeout=30,
            )
        elif get_resp.status_code == 404:
            post_url = f"{self.base_url}/buckets/{self.bucket_slug}/objects"
            resp = requests.post(
                post_url,
                headers=headers,
                data=json.dumps(payload),
                timeout=30,
            )
        else:
            get_resp.raise_for_status()

        resp.raise_for_status()
        return resp.json()
